package io.atlas.modules.research.repository;
import io.atlas.modules.database.DatabaseConfig;
import io.atlas.modules.research.model.ResearchPlan;
import java.sql.*;import java.util.*;
public final class ResearchRepository {
 public record Capture(UUID pokemon,UUID player,String species,List<String> types,long capturedAt){}
 public record Payment(UUID id,UUID player,String track,int stage,long amount,String state){}
 public record Summary(long captures,long species,long types,List<Payment> payments){public long progress(String track){return switch(track){case "captures"->captures;case "species"->species;case "types"->types;default->throw new IllegalArgumentException();};}}
 private Connection connect()throws SQLException{var props=new Properties();props.setProperty("user",DatabaseConfig.USER);props.setProperty("password",DatabaseConfig.PASSWORD);props.setProperty("connectTimeout","3");props.setProperty("socketTimeout","10");return DriverManager.getConnection(DatabaseConfig.jdbcUrl(),props);}
 public boolean record(Capture capture){try(var c=connect();var p=c.prepareStatement("INSERT INTO research_captures(pokemon_uuid,uuid,species,types,captured_at) SELECT ?,?,?,?,? WHERE NOT EXISTS(SELECT 1 FROM pokedex_rewards WHERE id=?) AND NOT EXISTS(SELECT 1 FROM commercial_vip_legendary_rewards WHERE pokemon_uuid=?) ON CONFLICT(pokemon_uuid) DO NOTHING")){p.setObject(1,capture.pokemon());p.setObject(2,capture.player());p.setString(3,capture.species());p.setArray(4,c.createArrayOf("text",capture.types().toArray()));p.setTimestamp(5,new Timestamp(capture.capturedAt()));p.setObject(6,capture.pokemon());p.setObject(7,capture.pokemon());return p.executeUpdate()==1;}catch(SQLException e){throw new IllegalStateException(e);}}
 private Payment row(ResultSet r)throws SQLException{return new Payment(r.getObject("id",UUID.class),r.getObject("uuid",UUID.class),r.getString("track"),r.getInt("stage"),r.getLong("amount"),r.getString("state"));}
 private Summary summary(Connection c,UUID player)throws SQLException{long captures,species,types;try(var p=c.prepareStatement("SELECT COUNT(*),COUNT(DISTINCT species) FROM research_captures WHERE uuid=?")){p.setObject(1,player);try(var r=p.executeQuery()){r.next();captures=r.getLong(1);species=r.getLong(2);}}try(var p=c.prepareStatement("SELECT COUNT(DISTINCT type) FROM research_captures CROSS JOIN unnest(types) AS type WHERE uuid=?")){p.setObject(1,player);try(var r=p.executeQuery()){r.next();types=r.getLong(1);}}var payments=new ArrayList<Payment>();try(var p=c.prepareStatement("SELECT * FROM research_payments WHERE uuid=? ORDER BY track,stage")){p.setObject(1,player);try(var r=p.executeQuery()){while(r.next())payments.add(row(r));}}return new Summary(captures,species,types,List.copyOf(payments));}
 public Summary summary(UUID player){try(var c=connect()){return summary(c,player);}catch(SQLException e){throw new IllegalStateException(e);}}
 public Optional<Payment> claim(UUID player,String track,int stage){var plan=ResearchPlan.stage(track,stage);try(var c=connect()){c.setAutoCommit(false);try{try(var p=c.prepareStatement("SELECT pg_advisory_xact_lock(?)")){p.setLong(1,player.getMostSignificantBits());p.executeQuery().close();}var snapshot=summary(c,player);boolean previous=stage==1||snapshot.payments().stream().anyMatch(r->r.track().equals(track)&&r.stage()==stage-1&&r.state().equals("PAID"));if(!previous||snapshot.progress(track)<plan.target()){c.rollback();return Optional.empty();}UUID id=UUID.randomUUID();try(var p=c.prepareStatement("INSERT INTO research_payments(id,uuid,track,stage,amount,state) VALUES(?,?,?,?,?,'PENDING') ON CONFLICT(uuid,track,stage) DO NOTHING")){p.setObject(1,id);p.setObject(2,player);p.setString(3,track);p.setInt(4,stage);p.setLong(5,plan.money());if(p.executeUpdate()!=1){c.rollback();return Optional.empty();}}c.commit();return Optional.of(new Payment(id,player,track,stage,plan.money(),"PENDING"));}catch(Exception e){c.rollback();throw e;}}catch(SQLException e){throw new IllegalStateException(e);}}
 public List<Payment> pending(){var out=new ArrayList<Payment>();try(var c=connect();var p=c.prepareStatement("SELECT * FROM research_payments WHERE state IN ('PENDING','PAYING') AND EXISTS(SELECT 1 FROM players p WHERE p.uuid=research_payments.uuid AND p.is_online) ORDER BY created_at LIMIT 100");var r=p.executeQuery()){while(r.next())out.add(row(r));return out;}catch(SQLException e){throw new IllegalStateException(e);}}
 public boolean transition(UUID id,String from,String to){if(!Set.of("PAYING","PAID","REVIEW","PENDING").contains(to))throw new IllegalArgumentException();try(var c=connect();var p=c.prepareStatement("UPDATE research_payments SET state=?,paid_at=CASE WHEN ?='PAID' THEN now() ELSE paid_at END WHERE id=? AND state=?")){p.setString(1,to);p.setString(2,to);p.setObject(3,id);p.setString(4,from);return p.executeUpdate()==1;}catch(SQLException e){throw new IllegalStateException(e);}}
}
